#!/usr/bin/env node
// Static site generator (zero dependencies).
//   node scripts/build.mjs           → regenerate every page, sitemap, robots, search index and assets
//   node scripts/build.mjs --check   → fail if any generated file is missing, stale or orphaned (CI gate)
import fs from 'node:fs';
import path from 'node:path';
import { ROOT, rel, shortHash, stripTags, fail } from './lib/util.mjs';
import { loadModel } from './lib/model.mjs';
import { buildTokens, plain } from './lib/text.mjs';
import { blockComponents } from './lib/components.mjs';
import { renderPage, render404 } from './lib/templates.mjs';
import { document } from './lib/layout.mjs';
import { jsonLd } from './lib/schema.mjs';
import { sitemap, robots, searchIndex, llmsTxt } from './lib/outputs.mjs';

const CHECK = process.argv.includes('--check');
const CSS_ORDER = ['tokens.css', 'base.css', 'layout.css', 'components.css', 'utilities.css', 'floating.css'];
// Folders that never contain generated pages (orphan scan skips them).
const SOURCE_DIRS = new Set(['.git', '.github', 'node_modules', 'assets', 'content', 'data', 'docs', 'factory', '_factory', 'reports', 'scripts', 'site', 'src']);

function minifyCss(css) {
  return css
    .replace(/\/\*[\s\S]*?\*\//g, '')
    .replace(/\s+/g, ' ')
    .replace(/\s*([{}:;,>])\s*/g, '$1')
    .replace(/;}/g, '}')
    .trim();
}

function bundleAssets(data) {
  const files = {};
  const cssParts = CSS_ORDER.filter((f) => fs.existsSync(rel('src/css', f))).map((f) => fs.readFileSync(rel('src/css', f), 'utf8'));
  if (!cssParts.length) fail('No CSS sources in src/css');
  const css = `/* Generated by scripts/build.mjs from src/css — do not edit */\n${minifyCss(cssParts.join('\n'))}\n`;
  files['assets/css/site.css'] = css;
  const app = fs.readFileSync(rel('src/js/app.js'), 'utf8');
  const search = fs.readFileSync(rel('src/js/search.js'), 'utf8');
  const banner = '/* Generated by scripts/build.mjs from src/js — do not edit */\n';
  files['assets/js/search.js'] = banner + search;
  const searchVersion = shortHash(search);
  files['assets/js/app.js'] = banner + app.replace('__SEARCH_SRC__', `/assets/js/search.js?v=${searchVersion}`);

  // Preserve the complete /web assistant, localised by an independent pt-PT adapter.
  for (const name of ['assistant.js', 'pt-assistant-adapter.js', 'floating.js']) {
    files[`assets/js/${name}`] = banner + fs.readFileSync(rel('src/js', name), 'utf8');
  }
  // Export public, owner-verified facts only. Never import /web prices or email.
  const b = data.business;
  const models = Object.fromEntries(data.pricing.models.map((m) => [
    m.id === 'eletrica' ? 'electric' : m.id,
    { name: m.name, cat: m.category, day: m.day, week: m.week, month: m.month }
  ]));
  const BUSINESS = {
    name: b.canonicalName, address: b.address.display,
    phone: b.phone.local, phoneTel: b.phone.e164, mapsUrl: b.maps,
    hoursText: b.hours.short, timezone: b.hours.timezone,
    openHour: Number(b.hours.opens.slice(0, 2)),
    closeHour: Number(b.hours.closes.slice(0, 2)),
    website: data.site.baseUrl,
    zaloUrl: b.zalo.enabled && b.zalo.verified ? b.zalo.url : ''
  };
  const CONTACT_METHODS = {
    call: {label:'Ligar',href:b.phone.tel,verified:true},
    zalo: {label:'Zalo',href:BUSINESS.zaloUrl,verified:!!BUSINESS.zaloUrl},
    maps: {label:'Maps',href:b.maps,verified:true},
    whatsapp: {label:'WhatsApp',href:b.whatsapp.url,verified:!!(b.whatsapp.enabled&&b.whatsapp.verified&&b.whatsapp.url)}
  };
  files['assets/js/business-config.js'] = banner +
    'var BUSINESS = ' + JSON.stringify(BUSINESS) + ';\n' +
    'var PRICES = ' + JSON.stringify(models) + ';\n' +
    'var CONTACT_METHODS = ' + JSON.stringify(CONTACT_METHODS) + ';\n';

  return {
    files,
    version: {
      css: shortHash(css), js: shortHash(files['assets/js/app.js']), search: searchVersion,
      business: shortHash(files['assets/js/business-config.js']),
      assistant: shortHash(files['assets/js/assistant.js']),
      adapter: shortHash(files['assets/js/pt-assistant-adapter.js']),
      floating: shortHash(files['assets/js/floating.js'])
    }
  };
}

function build() {
  const model = loadModel();
  const data = model.data;
  const assets = bundleAssets(data);
  const faqPage = model.pages.find((p) => p.template === 'faq');
  const faqById = new Map();
  for (const item of faqPage ? faqPage.groups.flatMap((g) => g.items) : []) {
    if (!item.id) continue;
    if (faqById.has(item.id)) fail(`Duplicate FAQ id ${item.id}`);
    faqById.set(item.id, item);
  }

  const base = {
    ...model,
    ui: data.ui,
    pricing: data.pricing,
    tokens: buildTokens(data),
    faqById,
    components: blockComponents,
    assetVersion: assets.version
  };

  // Business facts in titles and meta descriptions also come from {{tokens}} (single source of truth).
  for (const page of model.pages) {
    const tctx = { tokens: base.tokens, where: page.source || page.url };
    page.title = plain(page.title, tctx);
    page.description = plain(page.description, tctx);
  }

  const out = { ...assets.files };
  const searchEntries = [];
  const linkErrors = [];

  for (const page of model.pages) {
    const links = [];
    const ctx = {
      ...base,
      where: page.source || page.url,
      usedIds: new Set(['conteudo', 'cta-title', 'relacionados', 'fontes', 'pesquisa', 'pesquisa-input', 'menu-movel']),
      headings: [],
      onInternalLink: (href) => links.push(href)
    };
    const { main, faqItems } = renderPage(page, ctx);
    for (const href of links) {
      const target = href.split('#')[0];
      if (!model.byUrl.has(target)) linkErrors.push(`${page.url} → ${href}`);
    }
    const html = document(page, ctx, { jsonLd: jsonLd(page, ctx, { faqItems }), main });
    out[page.file] = html;
    if (page.indexable) {
      searchEntries.push({
        url: page.url,
        title: stripTags(page.h1),
        description: page.description,
        headings: ctx.headings.map((h) => h.text).filter((t) => t !== data.ui.sources).slice(0, 40),
        category: page.child ? model.children.get(page.child).label : page.parent ? model.parents.get(page.parent).label : ''
      });
    }
  }
  if (linkErrors.length) fail(`Broken internal links in content:\n  ${linkErrors.join('\n  ')}`);

  // 404 page: noindex, no canonical, excluded from sitemap and search.
  const notFound = { url: '/404.html', file: '404.html', template: 'page', kind: 'page', title: `${data.ui.notFoundTitle} | ${data.business.shortName}`, description: 'A página procurada não existe. Use a pesquisa ou volte às secções principais do site.', h1: data.ui.notFoundTitle, indexable: false, canonical: false, breadcrumb: [] };
  const ctx404 = { ...base, where: '404', usedIds: new Set(), headings: [], onInternalLink: () => {} };
  out['404.html'] = document(notFound, ctx404, { jsonLd: '', main: render404(ctx404) });

  out['sitemap.xml'] = sitemap(model.pages, base);
  out['robots.txt'] = robots(base);
  out['assets/search-index.json'] = searchIndex(searchEntries) + '\n';

  // Same rich, entirely local paragraph-search contract as /web's assistant.
  // Loaded only after the visitor opens the assistant; no third-party API.
  const chatEntries = searchEntries.map((item) => {
    const page = model.byUrl.get(item.url);
    const html = page ? out[page.file] || '' : '';
    const main = html.match(/<main\b[^>]*>([\s\S]*?)<\/main>/i)?.[1] || '';
    const heads = [...main.matchAll(/<h2\b[^>]*>([\s\S]*?)<\/h2>/gi)]
      .map((m) => stripTags(m[1]).replace(/\s+/g, ' ').trim());
    const chunks = main.split(/<h2\b[^>]*>[\s\S]*?<\/h2>/gi);
    const paras = (chunk) => [...chunk.matchAll(/<p\b[^>]*>([\s\S]*?)<\/p>/gi)]
      .map((m) => stripTags(m[1]).replace(/\s+/g, ' ').trim().slice(0, 400))
      .filter((txt) => txt.length > 35).slice(0, 2);
    const sections = [{h:'', p:paras(chunks[0] || '')}].concat(
      heads.slice(0, 20).map((h, i) => ({h, p:paras(chunks[i + 1] || '')}))
    );
    return {u:item.url, t:item.title, head:item.headings, s:sections};
  });
  out['assets/chat/search-index.json'] = JSON.stringify({
    version:'pt-PT-1', site:data.site.baseUrl, e:chatEntries
  }) + '\n';

  out['llms.txt'] = llmsTxt(model.pages, base);
  const indexNow = data.site.indexNow;
  if (indexNow?.enabled) {
    if (!/^[a-f0-9]{32,128}$/.test(indexNow.key || '')) fail('site.indexNow.key must be 32–128 hexadecimal characters');
    out[`${indexNow.key}.txt`] = indexNow.key;
  }
  return { out, model };
}

function findOrphans(expected) {
  const orphans = [];
  const walk = (dir) => {
    for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
      const full = path.join(dir, entry.name);
      const relative = path.relative(ROOT, full);
      if (entry.isDirectory()) {
        if (dir === ROOT && SOURCE_DIRS.has(entry.name)) continue;
        walk(full);
      } else if ((entry.name === 'index.html' || (dir === ROOT && /^[a-f0-9]{32,128}\.txt$/.test(entry.name))) && !expected.has(relative.split(path.sep).join('/'))) {
        orphans.push(relative);
      }
    }
  };
  walk(ROOT);
  return orphans;
}

try {
  const { out, model } = build();
  const expected = new Set(Object.keys(out));
  let stale = 0;
  for (const [file, content] of Object.entries(out)) {
    const full = rel(file);
    const current = fs.existsSync(full) ? fs.readFileSync(full, 'utf8') : null;
    if (current === content) continue;
    if (CHECK) {
      stale++;
      console.error(`STALE ${file}`);
    } else {
      fs.mkdirSync(path.dirname(full), { recursive: true });
      fs.writeFileSync(full, content, 'utf8');
    }
  }
  const orphans = findOrphans(expected);
  for (const file of orphans) {
    if (CHECK) console.error(`ORPHAN ${file} (no longer generated)`);
    else {
      fs.rmSync(rel(file));
      console.log(`removed orphan ${file}`);
    }
  }
  if (CHECK && (stale || orphans.length)) {
    console.error(`\n${stale} stale and ${orphans.length} orphan file(s). Run: node scripts/build.mjs`);
    process.exit(1);
  }
  const pages = model.pages.length;
  console.log(`${CHECK ? 'Verified' : 'Generated'} ${expected.size} files · ${pages} pages (${model.articles.length} articles, ${model.pages.filter((p) => p.indexable).length} indexable)`);
} catch (err) {
  console.error(err.isBuildError ? `BUILD ERROR: ${err.message}` : err);
  process.exit(1);
}
